import{_ as r,C as l,o as s,c as i,a4 as e,j as d,E as g}from"./chunks/framework.BUqnS5H7.js";const m=JSON.parse('{"title":"认识 PostgreSQL","description":"","frontmatter":{"doc_id":"pg-overview","title":"认识 PostgreSQL"},"headers":[],"relativePath":"postgresql/01-pg-unique/chapter-01-pg-overview.md","filePath":"postgresql/01-pg-unique/chapter-01-pg-overview.md"}'),p={name:"postgresql/01-pg-unique/chapter-01-pg-overview.md"},n={"data-src-line":"239","data-src-file":"postgresql/01-pg-unique/chapter-01-pg-overview.md"};function o(c,t,u,h,q,v){const a=l("SvgDiagram");return s(),i("div",null,[t[0]||(t[0]=e(`<h1 id="认识-postgresql" tabindex="-1" data-src-line="2" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">认识 PostgreSQL <a class="header-anchor" href="#认识-postgresql" aria-label="Permalink to &quot;认识 PostgreSQL&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><p data-src-line="4" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PostgreSQL 的历史、核心能力与适用场景。</p></blockquote><h2 id="_1-概述" tabindex="-1" data-src-line="6" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p data-src-line="8" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PostgreSQL（常简称 Postgres）是一个开源的<strong>对象-关系型数据库管理系统（ORDBMS）</strong>，用 C 语言编写，采用宽松的类 BSD 许可证。</p><p data-src-line="10" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">官方给自己的定位是&quot;全球最先进的开源关系数据库&quot;。这个定位不谦虚，但 PG 确实有几个其他开源数据库没有的东西：</p><table tabindex="0"><thead data-src-line="12" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="12" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">特征</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="14" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="14" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>SQL 标准</strong></td><td style="text-align:left;">严格遵循，兼容性最强</td></tr><tr data-src-line="15" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>可扩展性</strong></td><td style="text-align:left;">类型、索引、函数、语言都能自定义</td></tr><tr data-src-line="16" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>数据完整性</strong></td><td style="text-align:left;">约束与触发器完善</td></tr><tr data-src-line="17" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>MVCC</strong></td><td style="text-align:left;">多版本并发控制，读写互不阻塞</td></tr></tbody></table><h2 id="_2-历史与起源" tabindex="-1" data-src-line="19" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">2. 历史与起源 <a class="header-anchor" href="#_2-历史与起源" aria-label="Permalink to &quot;2. 历史与起源&quot;">​</a></h2><p data-src-line="21" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PG 的源头是加州大学伯克利分校（UC Berkeley）的 <strong>POSTGRES 项目</strong>，1986 年由 <strong>Michael Stonebraker（迈克尔·斯通布雷克）</strong> 主导启动。他是数据库领域奠基性人物，2014 年因&quot;对现代数据库系统底层概念与实践的根本性贡献&quot;获得图灵奖。</p><p data-src-line="23" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">POSTGRES 这个名字道出了它的血缘——<strong>&quot;Post Ingres&quot;</strong>，意为&quot;Ingres 之后&quot;。Ingres 是 Stonebraker 在 1973–1985 年领导的伯克利早期关系数据库项目，POSTGRES 正是它的后继者。</p><table tabindex="0"><thead data-src-line="25" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="25" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">阶段</th><th style="text-align:left;">时间</th><th style="text-align:left;">性质</th></tr></thead><tbody data-src-line="27" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="27" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">Ingres</td><td style="text-align:left;">1973–1985</td><td style="text-align:left;">伯克利早期关系数据库项目</td></tr><tr data-src-line="28" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">POSTGRES</td><td style="text-align:left;">1986–1994</td><td style="text-align:left;">研究型原型，无 SQL，专注对象-关系模型</td></tr><tr data-src-line="29" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">Postgres95</td><td style="text-align:left;">1994–1996</td><td style="text-align:left;">两个伯克利研究生给它加上 SQL 解释器</td></tr><tr data-src-line="30" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">PostgreSQL</td><td style="text-align:left;">1996-07-08</td><td style="text-align:left;">开源社区接管，发布首个版本 6.0</td></tr></tbody></table><p data-src-line="32" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">所以&quot;设计人&quot;分两层：<strong>架构奠基者是 Stonebraker 和他的伯克利团队</strong>，今天维护它的是社区（见 <a href="#who-maintains">§9</a>）。Stonebraker 本人早已不参与日常开发。</p><h3 id="起源动机" tabindex="-1" data-src-line="34" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">起源动机 <a class="header-anchor" href="#起源动机" aria-label="Permalink to &quot;起源动机&quot;">​</a></h3><p data-src-line="36" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">POSTGRES 不是要做一个新产品抢市场，而是源于 Ingres 暴露出的架构局限，属学术研究驱动：</p><ol data-src-line="38" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="38" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>类型系统僵化</strong>。Ingres 时期的关系模型只能存固定类型，无法表达复杂数据。Stonebraker 想做的是允许<strong>用户自定义类型、操作符、索引方法</strong>的数据库。</li><li data-src-line="39" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>数据完整性靠应用层兜底</strong>。早期关系数据库缺少声明式约束，POSTGRES 引入了更完整的主键、外键、检查约束，把完整性规则写进数据库本身。</li><li data-src-line="40" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>对象-关系模型的实验</strong>。这是 POSTGRES 最核心的学术贡献：在关系模型之上叠加&quot;对象&quot;能力（复杂类型、继承、可扩展类型系统），试图融合关系数据库与面向对象数据库两派优点。</li></ol><p data-src-line="42" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>Ingres 解决了&quot;怎么存关系数据&quot;，POSTGRES 要回答&quot;下一代数据库怎么做得更通用、更可扩展&quot;</strong>。1994 年补上 SQL 之后，它才从研究原型变成工程上可用的产品。</p><h2 id="_3-市场份额与流行度" tabindex="-1" data-src-line="44" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3. 市场份额与流行度 <a class="header-anchor" href="#_3-市场份额与流行度" aria-label="Permalink to &quot;3. 市场份额与流行度&quot;">​</a></h2><h3 id="_3-1-db-engines-全球排名" tabindex="-1" data-src-line="46" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3.1 DB-Engines 全球排名 <a class="header-anchor" href="#_3-1-db-engines-全球排名" aria-label="Permalink to &quot;3.1 DB-Engines 全球排名&quot;">​</a></h3><p data-src-line="48" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">DB-Engines 是业界最权威的数据库流行度排名，综合搜索热度、讨论频率、招聘需求等指标。截至 2026 年 6 月：</p><table tabindex="0"><thead data-src-line="50" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="50" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">排名</th><th style="text-align:left;">数据库</th><th style="text-align:left;">得分</th><th style="text-align:left;">月变化</th><th style="text-align:left;">年变化</th></tr></thead><tbody data-src-line="52" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="52" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">1</td><td style="text-align:left;">Oracle</td><td style="text-align:left;">1140.04</td><td style="text-align:left;">-3.24</td><td style="text-align:left;">-90.35</td></tr><tr data-src-line="53" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">2</td><td style="text-align:left;">MySQL</td><td style="text-align:left;">856.29</td><td style="text-align:left;">-0.21</td><td style="text-align:left;">-97.29</td></tr><tr data-src-line="54" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">3</td><td style="text-align:left;">SQL Server</td><td style="text-align:left;">698.04</td><td style="text-align:left;">-2.95</td><td style="text-align:left;">-78.71</td></tr><tr data-src-line="55" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>4</strong></td><td style="text-align:left;"><strong>PostgreSQL</strong></td><td style="text-align:left;"><strong>688.23</strong></td><td style="text-align:left;"><strong>+5.55</strong></td><td style="text-align:left;"><strong>+7.58</strong></td></tr></tbody></table><blockquote data-src-line="57" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><p data-src-line="57" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">前四名中，<strong>只有 PostgreSQL 实现了月度和年度双增长</strong>。其他三家全部下跌。PostgreSQL 距离 SQL Server 仅差 9.81 分，按当前增速，预计 2026 年内超越 SQL Server，打破维持二十年的 Oracle-MySQL-SQL Server 铁三角格局。</p><p data-src-line="59" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">— <a href="https://db-engines.com/en/ranking" target="_blank" rel="noreferrer">DB-Engines 排名（2026-06）</a> / <a href="https://www.modb.pro/db/2064162363633393664" target="_blank" rel="noreferrer">墨天轮分析</a></p></blockquote><p data-src-line="61" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PostgreSQL 曾 <strong>4 次</strong> 获得 DB-Engines &quot;年度数据库&quot; 奖（2017、2018、2019、2023），是获奖次数最多的数据库。</p><h3 id="_3-2-stack-overflow-开发者调查" tabindex="-1" data-src-line="63" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3.2 Stack Overflow 开发者调查 <a class="header-anchor" href="#_3-2-stack-overflow-开发者调查" aria-label="Permalink to &quot;3.2 Stack Overflow 开发者调查&quot;">​</a></h3><p data-src-line="65" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">Stack Overflow 年度开发者调查是全球最大的开发者调研，样本量超 6 万人：</p><table tabindex="0"><thead data-src-line="67" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="67" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">年份</th><th style="text-align:left;">PostgreSQL 使用率</th><th style="text-align:left;">排名</th><th style="text-align:left;">趋势</th></tr></thead><tbody data-src-line="69" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="69" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">2022</td><td style="text-align:left;">43.6%</td><td style="text-align:left;">#2</td><td style="text-align:left;">—</td></tr><tr data-src-line="70" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">2023</td><td style="text-align:left;">45.6%</td><td style="text-align:left;">#1</td><td style="text-align:left;">↑ 首次登顶</td></tr><tr data-src-line="71" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">2024</td><td style="text-align:left;">48.7%</td><td style="text-align:left;">#1</td><td style="text-align:left;">↑ 连续两年</td></tr><tr data-src-line="72" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">2025</td><td style="text-align:left;">55.6%</td><td style="text-align:left;">#1</td><td style="text-align:left;">↑ 历史最大年增幅（+7pp）</td></tr></tbody></table><p data-src-line="74" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PostgreSQL 已连续三年蝉联 &quot;最受欢迎数据库&quot; &quot;最想使用数据库&quot; &quot;最受认可数据库&quot; 三项冠军。</p><blockquote data-src-line="76" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><p data-src-line="76" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">— <a href="https://survey.stackoverflow.co/2025/" target="_blank" rel="noreferrer">Stack Overflow 2025 开发者调查</a> / <a href="https://survey.stackoverflow.co/2024/" target="_blank" rel="noreferrer">Stack Overflow 2024 开发者调查</a></p></blockquote><h3 id="_3-3-资本市场投票" tabindex="-1" data-src-line="78" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3.3 资本市场投票 <a class="header-anchor" href="#_3-3-资本市场投票" aria-label="Permalink to &quot;3.3 资本市场投票&quot;">​</a></h3><p data-src-line="80" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">2025 年，PostgreSQL 生态发生了超过 <strong>12.5 亿美元</strong> 的资本运作：</p><table tabindex="0"><thead data-src-line="82" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="82" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">事件</th><th style="text-align:left;">金额</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="84" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="84" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">Databricks 收购 Neon</td><td style="text-align:left;">~10 亿美元</td><td style="text-align:left;">PostgreSQL 云原生 Serverless 厂商</td></tr><tr data-src-line="85" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">Supabase D 轮融资</td><td style="text-align:left;">20 亿美元估值</td><td style="text-align:left;">PostgreSQL 后端即服务</td></tr><tr data-src-line="86" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">Snowflake 收购 Crunchy Data</td><td style="text-align:left;">~2.5 亿美元</td><td style="text-align:left;">PostgreSQL 企业发行版</td></tr><tr data-src-line="87" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">微软发布 Azure HorizonDB</td><td style="text-align:left;">—</td><td style="text-align:left;">基于 PostgreSQL 协议的 AI 原生数据库</td></tr></tbody></table><blockquote data-src-line="89" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><p data-src-line="89" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">全球最大的数据公司和云厂商，不约而同地将筹码押在了 PostgreSQL 上。</p></blockquote><h2 id="_4-性能跑分-benchmark" tabindex="-1" data-src-line="91" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">4. 性能跑分（Benchmark） <a class="header-anchor" href="#_4-性能跑分-benchmark" aria-label="Permalink to &quot;4. 性能跑分（Benchmark）&quot;">​</a></h2><h3 id="_4-1-pgbench-内置基准" tabindex="-1" data-src-line="93" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">4.1 pgbench 内置基准 <a class="header-anchor" href="#_4-1-pgbench-内置基准" aria-label="Permalink to &quot;4.1 pgbench 内置基准&quot;">​</a></h3><p data-src-line="95" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">pgbench 是 PG 自带的 TPC-B 式压测工具，适合快速评估硬件和配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 初始化（scale=100 约 1000 万行）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgbench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mydb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 运行 60 秒，32 并发</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgbench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mydb</span></span></code></pre></div><p data-src-line="105" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">典型结果（8 核 32GB 内存，NVMe SSD，PG 16 默认配置）：</p><table tabindex="0"><thead data-src-line="107" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="107" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">并发数</th><th style="text-align:left;">TPS</th><th style="text-align:left;">平均延迟</th><th style="text-align:left;">99% 延迟</th></tr></thead><tbody data-src-line="109" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="109" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">1</td><td style="text-align:left;">~2,500</td><td style="text-align:left;">0.4ms</td><td style="text-align:left;">0.8ms</td></tr><tr data-src-line="110" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">8</td><td style="text-align:left;">~18,000</td><td style="text-align:left;">0.44ms</td><td style="text-align:left;">1.2ms</td></tr><tr data-src-line="111" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">32</td><td style="text-align:left;">~45,000</td><td style="text-align:left;">0.71ms</td><td style="text-align:left;">2.5ms</td></tr><tr data-src-line="112" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">64</td><td style="text-align:left;">~52,000</td><td style="text-align:left;">1.23ms</td><td style="text-align:left;">5.8ms</td></tr><tr data-src-line="113" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">128</td><td style="text-align:left;">~48,000</td><td style="text-align:left;">2.67ms</td><td style="text-align:left;">12.3ms</td></tr></tbody></table><blockquote data-src-line="115" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><p data-src-line="115" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">以上为参考值，实际性能取决于硬件、配置（shared_buffers、work_mem）、数据规模等因素。</p></blockquote><h3 id="_4-2-tpc-c-事务处理-oltp" tabindex="-1" data-src-line="117" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">4.2 TPC-C 事务处理（OLTP） <a class="header-anchor" href="#_4-2-tpc-c-事务处理-oltp" aria-label="Permalink to &quot;4.2 TPC-C 事务处理（OLTP）&quot;">​</a></h3><p data-src-line="119" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">TPC-C 是业界标准的 OLTP 基准测试，模拟电商订单场景（新订单、付款、查询、配送、库存）。</p><p data-src-line="121" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">使用 BenchmarkSQL 测试工具，典型结果对比：</p><table tabindex="0"><thead data-src-line="123" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="123" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">数据库</th><th style="text-align:left;">tpmC（8 核）</th><th style="text-align:left;">tpmC（32 核）</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="125" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="125" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">PostgreSQL 16</td><td style="text-align:left;">~12,000</td><td style="text-align:left;">~45,000</td><td style="text-align:left;">默认配置，单节点</td></tr><tr data-src-line="126" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">MySQL 8.0 (InnoDB)</td><td style="text-align:left;">~12,500</td><td style="text-align:left;">~42,000</td><td style="text-align:left;">默认配置，单节点</td></tr></tbody></table><blockquote data-src-line="128" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><p data-src-line="128" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">在标准 OLTP 场景下，PG 与 MySQL 性能基本持平。PG 的优势在复杂查询（并行查询、JIT 编译）和高级特性（JSONB、窗口函数）。</p><p data-src-line="130" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">— <a href="https://github.com/benchmarksql/benchmarksql" target="_blank" rel="noreferrer">BenchmarkSQL 工具</a> / <a href="https://www.enterprisedb.com/blog/how-to-run-a-complex-postgres-benchmark-tpc-c-pgbench" target="_blank" rel="noreferrer">EDB TPC-C 测试教程</a></p></blockquote><h3 id="_4-3-复杂查询-olap" tabindex="-1" data-src-line="132" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">4.3 复杂查询（OLAP） <a class="header-anchor" href="#_4-3-复杂查询-olap" aria-label="Permalink to &quot;4.3 复杂查询（OLAP）&quot;">​</a></h3><p data-src-line="134" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PG 在复杂分析查询上有明显优势，得益于<strong>并行查询</strong>和 <strong>JIT 编译</strong>：</p><table tabindex="0"><thead data-src-line="136" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="136" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">场景</th><th style="text-align:left;">PostgreSQL 16</th><th style="text-align:left;">MySQL 8.0</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="138" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="138" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">多表 JOIN + 聚合</td><td style="text-align:left;">1x（基准）</td><td style="text-align:left;">2-5x 慢</td><td style="text-align:left;">PG 并行查询优势</td></tr><tr data-src-line="139" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">窗口函数</td><td style="text-align:left;">1x</td><td style="text-align:left;">3-8x 慢</td><td style="text-align:left;">PG 原生优化更成熟</td></tr><tr data-src-line="140" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">JSONB 路径查询</td><td style="text-align:left;">1x</td><td style="text-align:left;">5-10x 慢</td><td style="text-align:left;">PG 的 GIN 索引 + 二进制 JSONB</td></tr><tr data-src-line="141" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">CTE 递归查询</td><td style="text-align:left;">1x</td><td style="text-align:left;">不支持/有限</td><td style="text-align:left;">PG 递归 CTE 完整支持</td></tr></tbody></table><blockquote data-src-line="143" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><p data-src-line="143" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>选型结论</strong>：纯 OLTP 场景两者性能相当；涉及复杂查询、JSONB、空间数据、向量检索等场景，PG 有显著优势。性能不是选型的决定性因素，<strong>功能需求和生态匹配才是</strong>。</p></blockquote><h2 id="_5-核心能力" tabindex="-1" data-src-line="145" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">5. 核心能力 <a class="header-anchor" href="#_5-核心能力" aria-label="Permalink to &quot;5. 核心能力&quot;">​</a></h2><h3 id="_3-1-类型系统" tabindex="-1" data-src-line="147" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3.1 类型系统 <a class="header-anchor" href="#_3-1-类型系统" aria-label="Permalink to &quot;3.1 类型系统&quot;">​</a></h3><p data-src-line="149" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PG 的类型系统是开源数据库里最丰富的：</p><ul data-src-line="151" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="151" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>数组类型</strong>：<code>TEXT[]</code>、<code>INT[]</code>，支持 GIN 索引</li><li data-src-line="152" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>范围类型</strong>：<code>tsrange</code>、<code>int4range</code>，支持 <code>@&gt;</code> 包含查询</li><li data-src-line="153" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>JSONB</strong>：二进制存储，支持 GIN 索引，查询性能远超文本 JSON</li><li data-src-line="154" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>枚举、复合类型、DOMAIN</strong>：自定义类型体系</li><li data-src-line="155" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>网络地址</strong>：<code>INET</code>、<code>CIDR</code>，支持网络运算</li></ul><h3 id="_3-2-索引类型" tabindex="-1" data-src-line="157" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3.2 索引类型 <a class="header-anchor" href="#_3-2-索引类型" aria-label="Permalink to &quot;3.2 索引类型&quot;">​</a></h3><p data-src-line="159" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PG 提供的索引类型远不止 B-tree：</p><table tabindex="0"><thead data-src-line="161" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="161" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">索引类型</th><th style="text-align:left;">适用场景</th></tr></thead><tbody data-src-line="163" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="163" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">B-tree</td><td style="text-align:left;">通用，等值/范围/排序</td></tr><tr data-src-line="164" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">GIN</td><td style="text-align:left;">JSONB、数组、全文检索</td></tr><tr data-src-line="165" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">GiST</td><td style="text-align:left;">地理信息、范围类型</td></tr><tr data-src-line="166" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">BRIN</td><td style="text-align:left;">超大时序表，索引极小</td></tr><tr data-src-line="167" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;">Hash</td><td style="text-align:left;">纯等值查询</td></tr></tbody></table><h3 id="_3-3-sql-能力" tabindex="-1" data-src-line="169" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3.3 SQL 能力 <a class="header-anchor" href="#_3-3-sql-能力" aria-label="Permalink to &quot;3.3 SQL 能力&quot;">​</a></h3><p data-src-line="171" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PG 的 SQL 方言在开源数据库里最强：</p><ul data-src-line="173" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="173" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>窗口函数</strong>：完整支持</li><li data-src-line="174" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>CTE 递归</strong>：查询树形结构</li><li data-src-line="175" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>RETURNING</strong>：INSERT/UPDATE/DELETE 后直接返回数据</li><li data-src-line="176" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>INSERT ON CONFLICT</strong>：原生 UPSERT</li><li data-src-line="177" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>FILTER 子句</strong>：条件聚合</li><li data-src-line="178" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>DISTINCT ON</strong>：PG 独有语法</li><li data-src-line="179" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>LATERAL JOIN</strong>：相关子查询优化</li></ul><h3 id="_3-4-事务与并发" tabindex="-1" data-src-line="181" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3.4 事务与并发 <a class="header-anchor" href="#_3-4-事务与并发" aria-label="Permalink to &quot;3.4 事务与并发&quot;">​</a></h3><ul data-src-line="183" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="183" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">默认 Read Committed</li><li data-src-line="184" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>SSI</strong>：真正的 Serializable，乐观并发控制</li><li data-src-line="185" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>4 种行锁</strong>：FOR UPDATE / FOR NO KEY UPDATE / FOR SHARE / FOR KEY SHARE</li><li data-src-line="186" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>咨询锁</strong>：PG 独有的应用层锁</li><li data-src-line="187" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>SKIP LOCKED</strong>：任务队列利器</li></ul><h3 id="_3-5-扩展生态" tabindex="-1" data-src-line="189" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">3.5 扩展生态 <a class="header-anchor" href="#_3-5-扩展生态" aria-label="Permalink to &quot;3.5 扩展生态&quot;">​</a></h3><p data-src-line="191" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">PG 的扩展机制让它不只是一个数据库：</p><ul data-src-line="193" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="193" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><code>pg_stat_statements</code>：查询统计</li><li data-src-line="194" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><code>pg_trgm</code>：模糊搜索</li><li data-src-line="195" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><code>pgvector</code>：向量搜索（AI 场景）</li><li data-src-line="196" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><code>TimescaleDB</code>：时序数据</li><li data-src-line="197" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><code>PostGIS</code>：空间数据</li><li data-src-line="198" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><code>pg_cron</code>：定时任务</li></ul><hr><h2 id="_6-与-mysql-的主要差异" tabindex="-1" data-src-line="202" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">6. 与 MySQL 的主要差异 <a class="header-anchor" href="#_6-与-mysql-的主要差异" aria-label="Permalink to &quot;6. 与 MySQL 的主要差异&quot;">​</a></h2><p data-src-line="204" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">如果你从 MySQL 过来，这些是最值得注意的区别：</p><p data-src-line="206" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>MVCC 实现</strong>：PG 把旧版本直接存回原表（堆表），读写互不阻塞，但需要定期 VACUUM 清理死元组。MySQL 用 Undo Log 存旧版本，空间回收交给后台线程，不需要手动维护，但高并发长事务下 Undo Log 膨胀是常见问题。</p><p data-src-line="208" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>SQL 标准遵循</strong>：MySQL 的 GROUP BY 可以不写全聚合字段，PG 必须写全——这看起来是&quot;不灵活&quot;，实际上是帮你避免写出结果不确定的查询。</p><table tabindex="0"><thead data-src-line="210" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="210" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">维度</th><th style="text-align:left;">PostgreSQL</th><th style="text-align:left;">MySQL</th></tr></thead><tbody data-src-line="212" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="212" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>SQL 标准</strong></td><td style="text-align:left;">严格遵循</td><td style="text-align:left;">部分宽松（如 GROUP BY）</td></tr><tr data-src-line="213" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>可扩展性</strong></td><td style="text-align:left;">类型、索引、语言均可扩展</td><td style="text-align:left;">扩展能力有限</td></tr><tr data-src-line="214" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>数据完整性</strong></td><td style="text-align:left;">强，约束和触发器完善</td><td style="text-align:left;">部分约束不支持</td></tr><tr data-src-line="215" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>MVCC 实现</strong></td><td style="text-align:left;">旧版本存堆表，需 VACUUM</td><td style="text-align:left;">Undo Log，自动回收</td></tr></tbody></table><h2 id="_7-选型参考" tabindex="-1" data-src-line="217" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">7. 选型参考 <a class="header-anchor" href="#_7-选型参考" aria-label="Permalink to &quot;7. 选型参考&quot;">​</a></h2><p data-src-line="219" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>选 PG 的典型场景：</strong></p><ul data-src-line="221" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="221" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">数据结构复杂，JSONB、数组、范围类型用得多</li><li data-src-line="222" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">查询复杂，窗口函数、CTE、子查询是日常</li><li data-src-line="223" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">需要地理信息（PostGIS）、向量搜索（pgvector）等扩展</li><li data-src-line="224" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">对 SQL 标准合规性有要求</li></ul><p data-src-line="226" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>不选 PG 的常见原因：</strong></p><ul data-src-line="228" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="228" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">高并发简单 CRUD，读写性能优先</li><li data-src-line="229" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">团队对 MySQL 更熟悉，生态更成熟</li><li data-src-line="230" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">国内云厂商支持更完善，部署更简单</li><li data-src-line="231" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">不需要 PG 那些高级特性，够用就行</li></ul><h2 id="_8-版本与生态" tabindex="-1" data-src-line="233" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">8. 版本与生态 <a class="header-anchor" href="#_8-版本与生态" aria-label="Permalink to &quot;8. 版本与生态&quot;">​</a></h2><h3 id="本站覆盖范围" tabindex="-1" data-src-line="235" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">本站覆盖范围 <a class="header-anchor" href="#本站覆盖范围" aria-label="Permalink to &quot;本站覆盖范围&quot;">​</a></h3><p data-src-line="237" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">本站聚焦 <strong>v14 / v15 / v16</strong> 版本，覆盖 JSONB、窗口函数、CTE、MVCC/VACUUM 等核心特性。</p>`,75)),d("p",n,[g(a,{src:"/pg/timeline.svg",alt:"PostgreSQL 关键版本"})]),t[1]||(t[1]=e('<h3 id="发布节奏" tabindex="-1" data-src-line="241" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">发布节奏 <a class="header-anchor" href="#发布节奏" aria-label="Permalink to &quot;发布节奏&quot;">​</a></h3><p data-src-line="243" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">自 PG 10（2017 年）起，发布节奏固定：</p><ul data-src-line="245" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="245" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">每年秋季（9 月底）发布一个大版本，每个大版本支持期约 <strong>5 年</strong>。</li><li data-src-line="246" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">小版本（修复版）按季度发布，固定在 2 / 5 / 8 / 11 月的第二个周四。</li><li data-src-line="247" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">大版本升级用 <code>pg_upgrade</code> 就地完成，无需 dump/reload。</li></ul><h3 id="当前状态-2026-08" tabindex="-1" data-src-line="249" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">当前状态（2026-08） <a class="header-anchor" href="#当前状态-2026-08" aria-label="Permalink to &quot;当前状态（2026-08）&quot;">​</a></h3><p data-src-line="251" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">官方最新稳定版是 <strong>18.6</strong>，19 已进入 Beta 3，预计 2026 年 9 月正式发布；正在维护的版本线为 14–18，其中 14 将于 2026-11-12 停止修复（EOL）。</p><p data-src-line="253" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">近年特性演进方向：JSONB（9.4）、逻辑复制与物理复制增强、并行查询、分区表性能、JIT 编译（11）、增量物化视图，以及 18 引入的异步 I/O 子系统。生态层靠扩展驱动——PostGIS（空间）、pgvector（向量检索）、TimescaleDB（时序）、Citus（分布式）。</p><h2 id="who-maintains" tabindex="-1" data-src-line="255" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">9. 社区与维护 <a class="header-anchor" href="#who-maintains" aria-label="Permalink to &quot;9. 社区与维护 {#who-maintains}&quot;">​</a></h2><p data-src-line="257" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>维护主体是 PostgreSQL Global Development Group（PGDG）</strong>，一个全球开发者社区，不属于任何一家公司。</p><ul data-src-line="259" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><li data-src-line="259" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>无单一厂商掌控</strong>。版权归 PGDG，宽松许可证允许任何人免费使用、修改甚至闭源商用，从根上杜绝了&quot;某家公司把 PG 商业化后闭源&quot;的锁定风险。</li><li data-src-line="260" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>治理结构</strong>：一个小型 Core Team 负责整体方向与发布管理；几十名长期贡献者拥有 commit 权限；贡献来自多家公司（EDB、Microsoft、Amazon、Google、Crunchy Data 等），但公司只贡献代码，不拥有项目。</li><li data-src-line="261" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><strong>安全运维</strong>：PGDG 统一发版、统一披露 CVE 安全公告，跟进官方小版本即可获得修复。</li></ul><p data-src-line="263" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md">运维生态分两层：</p><table tabindex="0"><thead data-src-line="265" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="265" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><th style="text-align:left;">模式</th><th style="text-align:left;">说明</th><th style="text-align:left;">适用场景</th></tr></thead><tbody data-src-line="267" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><tr data-src-line="267" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>自建自管</strong></td><td style="text-align:left;">社区源码 + 二进制包（<code>apt.postgresql.org</code> 等）</td><td style="text-align:left;">有 DBA 团队的场景</td></tr><tr data-src-line="268" data-src-file="postgresql/01-pg-unique/chapter-01-pg-overview.md"><td style="text-align:left;"><strong>托管服务</strong></td><td style="text-align:left;">云厂商（AWS RDS、Azure、GCP Cloud SQL/AlloyDB）与专门公司（EDB、Crunchy Data、Neon、Supabase、Timescale）</td><td style="text-align:left;">缺运维团队或追求弹性</td></tr></tbody></table>',11))])}const y=r(p,[["render",o]]);export{m as __pageData,y as default};
